# ae_info —— 探测 AE 安装 + 桥接/权限自检（只读，不启动 AE）
$ErrorActionPreference = 'Stop'
$roots = @('C:\Program Files\Adobe', 'C:\Program Files (x86)\Adobe')
$dirs = @()
foreach ($r in $roots) {
  if (Test-Path $r) {
    $dirs += Get-ChildItem -Path $r -Directory -Filter 'Adobe After Effects *' -ErrorAction SilentlyContinue
  }
}
$dirs = $dirs | Sort-Object Name -Descending
if (-not $dirs -or $dirs.Count -eq 0) {
  Write-Output '未找到 After Effects：已扫描 C:\Program Files\Adobe 与 C:\Program Files (x86)\Adobe 下的 Adobe After Effects * 目录。'
  exit 2
}
$found = $false
foreach ($d in $dirs) {
  $exe = Join-Path $d.FullName 'Support Files\AfterFX.exe'
  $ar  = Join-Path $d.FullName 'Support Files\aerender.exe'
  if (Test-Path $exe) {
    $found = $true
    $v = (Get-Item $exe).VersionInfo.FileVersion
    Write-Output ("AE 安装：" + $exe)
    Write-Output ("版本：" + $v)
    if (Test-Path $ar) { Write-Output ("渲染器：" + $ar) }
  }
}
if (-not $found) { Write-Output '找到目录但目录里没有 Support Files\AfterFX.exe（安装可能不完整）'; exit 2 }
# 桥接守护自检
$aeData = Get-ChildItem "$env:APPDATA\Adobe\After Effects" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^\d+\.\d+$' } | Sort-Object Name -Descending | Select-Object -First 1
if ($aeData) {
  $bridge = Join-Path $aeData.FullName 'Scripts\Startup\parable-bridge.jsx'
  if (Test-Path $bridge) { Write-Output ('桥接守护：已安装 ' + $bridge) }
  else { Write-Output '桥接守护：未安装（ae_script 首次调用会自动安装）' }
  # 脚本写文件权限（首选项落盘于 AE 退出时，运行中读取的是上次退出状态）
  $prefHit = Get-ChildItem $aeData.FullName -Filter '*.txt' -ErrorAction SilentlyContinue | ForEach-Object { Select-String -Path $_.FullName -Pattern 'Allow Scripts to Write Files' -SimpleMatch -ErrorAction SilentlyContinue } | Select-Object -First 1
  if ($prefHit) { Write-Output ('脚本写文件权限（上次退出时状态）：' + $prefHit.Line.Trim()) }
  else { Write-Output '脚本写文件权限：首选项里没有该键（新装默认关闭）。请在 AE 「设置 > 脚本和表达式」里开启「允许脚本写入文件和访问网络」。' }
}
Write-Output '通道说明：AE 2025+ 的 AfterFX.exe -r/-s 脚本通道已废弃（实测与社区一致），本插件用 Startup 守护桥 + 收件箱轮询。'

# ae_script —— Startup 守护桥 + 收件箱轮询
$ErrorActionPreference = 'Stop'
$a = $null
try { $a = $env:PARABLE_TOOL_ARGS | ConvertFrom-Json } catch { $a = $null }
if (-not $a -or -not $a.code) { Write-Output '缺少 code 参数（ExtendScript 代码）'; exit 2 }
$code = [string]$a.code
$timeoutSec = 100
if ($a.timeout) { $timeoutSec = [Math]::Min(110, [int]$a.timeout) }

# 1. 定位最新 AE（可执行文件 + 用户脚本目录）
$exe = $null; $aeVerDir = $null
foreach ($root in @('C:\Program Files\Adobe', 'C:\Program Files (x86)\Adobe')) {
  if (Test-Path $root) {
    foreach ($d in (Get-ChildItem -Path $root -Directory -Filter 'Adobe After Effects *' -ErrorAction SilentlyContinue | Sort-Object Name -Descending)) {
      $cand = Join-Path $d.FullName 'Support Files\AfterFX.exe'
      if ((Test-Path $cand) -and (-not $exe)) { $exe = $cand }
    }
  }
}
if (-not $exe) { Write-Output '未找到 AfterFX.exe：先运行 ae_info。'; exit 2 }
# 只认纯版本号数据目录（排除 已隔离/old/Logs 等干扰项）
$aeData = Get-ChildItem "$env:APPDATA\Adobe\After Effects" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -match '^\d+\.\d+$' } | Sort-Object Name -Descending | Select-Object -First 1
if (-not $aeData) { Write-Output '找不到 %APPDATA%\Adobe\After Effects 数据目录（AE 至少完整启动过一次才有）。'; exit 2 }

# 2. 安装/刷新 Startup 守护桥
$startupDir = Join-Path $aeData.FullName 'Scripts\Startup'
New-Item -ItemType Directory -Force -Path $startupDir | Out-Null
$bridgePath = Join-Path $startupDir 'parable-bridge.jsx'
$bridge = @'
// Parable 桥：AE 启动时自动加载，轮询收件箱并执行载荷脚本。
// 载荷通过 File 写结果文件回传——需要「允许脚本写入文件和访问网络」首选项开启。
(function () {
    var TASK = "(function(){ var t=Folder.temp.fullName; var fs=new Folder(t).getFiles('parable-ae-bridge-*.cmd'); for(var i=0;i<fs.length;i++){ var tf=fs[i]; var pp=''; try{ tf.open('r'); pp=tf.read(); tf.close(); tf.remove(); }catch(eRead){ continue; } if(!pp) continue; try{ var pf=new File(pp); if(pf.exists){ pf.encoding='UTF-8'; pf.open('r'); var code=pf.read(); pf.close(); (new Function(code))(); } }catch(eExec){ var ef=new File(pp+'.err'); try{ ef.open('w'); ef.write('BRIDGE-ERR '+eExec.toString()+' @line '+eExec.line); ef.close(); }catch(e2){} } } })()";
    try { (new Function(TASK))(); } catch (e0) {}
    try { app.scheduleTask(TASK, 600, true); } catch (e1) {}
})();
'@
$utf8Bom = New-Object System.Text.UTF8Encoding($true)
$needWrite = $true
if (Test-Path $bridgePath) {
    $old = [System.IO.File]::ReadAllText($bridgePath)
    if ($old -eq $bridge) { $needWrite = $false }
}
if ($needWrite) { [System.IO.File]::WriteAllText($bridgePath, $bridge, $utf8Bom); Write-Output ('桥接守护已安装：' + $bridgePath) }

# 3. 确保 AE 在运行（守护桥随 AE 启动加载）
$coldStart = $false
$running = Get-Process -Name 'AfterFX' -ErrorAction SilentlyContinue
if (-not $running) {
    Start-Process -FilePath $exe | Out-Null
    $coldStart = $true
    Write-Output 'AE 未运行：已启动（冷启动约 40-90 秒，启动完成后守护桥自动就位）。'
}

# 4. 写载荷与收件箱
$outFile = Join-Path $env:TEMP ('parable-ae-res-' + [guid]::NewGuid().ToString('N') + '.txt')
$outJsx = ($outFile -replace '\\', '/')
$payloadFile = Join-Path $env:TEMP ('parable-ae-payload-' + [guid]::NewGuid().ToString('N') + '.jsx')
$wrapper = @"
var __P_OUT = `"$outJsx`";
try {
  var __P_RES = (function(){
$code
  })();
  var __P_F = new File(__P_OUT);
  __P_F.encoding = 'UTF-8';
  __P_F.open('w');
  __P_F.write('OK ' + String(__P_RES));
  __P_F.close();
} catch (e) {
  var __P_F2 = new File(__P_OUT);
  __P_F2.encoding = 'UTF-8';
  __P_F2.open('w');
  __P_F2.write('ERR ' + e.toString() + ' (line ' + e.line + ')');
  __P_F2.close();
}
"@
[System.IO.File]::WriteAllText($payloadFile, $wrapper, $utf8Bom)
$triggerFile = Join-Path $env:TEMP ('parable-ae-bridge-' + [guid]::NewGuid().ToString('N') + '.cmd')
[System.IO.File]::WriteAllText($triggerFile, $payloadFile, (New-Object System.Text.UTF8Encoding($false)))

# 5. 轮询结果
$deadline = (Get-Date).AddSeconds($timeoutSec)
while ((Get-Date) -lt $deadline) {
  Start-Sleep -Milliseconds 800
  if (Test-Path $outFile) {
    $res = [System.IO.File]::ReadAllText($outFile)
    Remove-Item $outFile, $payloadFile -ErrorAction SilentlyContinue
    Write-Output $res
    if ($res -like 'ERR*') { exit 1 }
    exit 0
  }
  if ($coldStart -and -not (Get-Process -Name 'AfterFX' -ErrorAction SilentlyContinue)) {
    break
  }
}
Remove-Item $triggerFile, $payloadFile -ErrorAction SilentlyContinue

# 6. 超时结构化自诊断
Write-Output "TIMEOUT：${timeoutSec}s 内未拿到结果。"
Write-Output '按顺序检查：'
if ($coldStart) { Write-Output '1) AE 刚冷启动——等它加载完（窗口出现后）用相同参数重试一次，通常秒回。' }
$prefHit = Get-ChildItem $aeData.FullName -Filter '*.txt' -ErrorAction SilentlyContinue | ForEach-Object { Select-String -Path $_.FullName -Pattern 'Allow Scripts to Write Files' -SimpleMatch -ErrorAction SilentlyContinue } | Select-Object -First 1
if ($prefHit -and $prefHit.Line -match '" 0\r?$| 0$') {
  Write-Output '2) 「允许脚本写入文件和访问网络」首选项是关闭的——桥读不到收件箱。在 AE 设置 > 脚本和表达式 里开启后重试（一次性设置）。'
} else {
  Write-Output '2) 确认 AE 设置 > 脚本和表达式 > 「允许脚本写入文件和访问网络」已开启（桥和载荷都需要写文件）。'
}
Write-Output '3) AE 启动时是否弹了模态警告框——去 AE 窗口点掉（警告内容如有必要请转述给用户）。'
Write-Output '4) 桥是否加载：AE 菜单 文件 > 脚本 里应能看到 Startup；本工具已在需要时自动安装桥到 Scripts\Startup\parable-bridge.jsx。'
exit 3

# ae_render —— aerender 渲染，110s 守护
$ErrorActionPreference = 'Stop'
$a = $null
try { $a = $env:PARABLE_TOOL_ARGS | ConvertFrom-Json } catch { $a = $null }
if (-not $a -or -not $a.project -or -not $a.output) { Write-Output '需要 project 与 output 参数'; exit 2 }

$ar = $null
foreach ($root in @('C:\Program Files\Adobe', 'C:\Program Files (x86)\Adobe')) {
  if (Test-Path $root) {
    foreach ($d in (Get-ChildItem -Path $root -Directory -Filter 'Adobe After Effects *' -ErrorAction SilentlyContinue | Sort-Object Name -Descending)) {
      $cand = Join-Path $d.FullName 'Support Files\aerender.exe'
      if (Test-Path $cand) { if (-not $ar) { $ar = $cand } }
    }
  }
}
if (-not $ar) { Write-Output '未找到 aerender.exe：先运行 ae_info。'; exit 2 }

$argList = @('-project', ('"' + $a.project + '"'))
if ($a.comp) { $argList += @('-comp', ('"' + $a.comp + '"')) }
if ($a.rs_template) { $argList += @('-RStemplate', ('"' + $a.rs_template + '"')) }
if ($a.om_template) { $argList += @('-OMtemplate', ('"' + $a.om_template + '"')) }
if ($a.start_frame) { $argList += @('-s', [string][int]$a.start_frame) }
if ($a.end_frame) { $argList += @('-e', [string][int]$a.end_frame) }
$argList += @('-output', ('"' + $a.output + '"'))

$so = Join-Path $env:TEMP ('parable-ae-rd-' + [guid]::NewGuid().ToString('N') + '.log')
$p = Start-Process -FilePath $ar -ArgumentList $argList -RedirectStandardOutput $so -PassThru -WindowStyle Hidden
Write-Output ('aerender 已启动 (pid ' + $p.Id + ')')
$deadline = (Get-Date).AddSeconds(110)
while (-not $p.HasExited -and (Get-Date) -lt $deadline) { Start-Sleep -Milliseconds 900 }
if (-not $p.HasExited) {
  try { $p.Kill() } catch {}
  $log = if (Test-Path $so) { [System.IO.File]::ReadAllText($so) } else { '' }
  if ($log) { Write-Output ('[已产出日志尾] ' + $log.Substring([Math]::Max(0, $log.Length - 2000))) }
  Write-Output 'TIMEOUT：渲染 110s 未完成已终止。大任务请按帧区间分块（start_frame/end_frame），或用 bash 工具挂后台终端跑完整渲染（不受 120s 限制）。'
  exit 3
}
$log = if (Test-Path $so) { [System.IO.File]::ReadAllText($so) } else { '' }
if ($log) {
  $tail = $log.Substring([Math]::Max(0, $log.Length - 4000))
  Write-Output $tail
}
if ($p.ExitCode -ne 0) { Write-Output ('[aerender 退出码 ' + $p.ExitCode + ']'); exit $p.ExitCode }
Remove-Item $so -ErrorAction SilentlyContinue
